'use client';

import * as React from 'react';
import { Highlight, themes } from 'prism-react-renderer';
import { cn } from '@/lib/utils';

export interface CodeBlockProps {
  /** Raw code to display (no trailing newline needed). */
  code: string;
  /** Language identifier used for Prism highlighting. */
  language?: string;
  /** Show a copy-to-clipboard button (default true). */
  showCopyButton?: boolean;
  className?: string;
}

const CodeBlock = React.forwardRef<HTMLDivElement, CodeBlockProps>(
  ({ code, language = 'tsx', showCopyButton = true, className, ...props }, ref) => {
    const [copied, setCopied] = React.useState(false);
    const trimmedCode = code.replace(/\n$/, '');

    const handleCopy = async () => {
      try {
        await navigator.clipboard.writeText(trimmedCode);
      } catch {
        // Clipboard unavailable (insecure context); still show feedback so
        // consumers can hook onCopy-style behavior via DOM if needed.
      }
      setCopied(true);
      window.setTimeout(() => setCopied(false), 2000);
    };

    return (
      <div
        ref={ref}
        className={cn(
          'relative group rounded-md border border-border bg-muted/50 overflow-hidden',
          className
        )}
        {...props}
      >
        <div className="flex items-center justify-between px-3 py-1.5 border-b border-border bg-muted/60">
          <span className="text-xs font-mono text-muted-foreground uppercase">{language}</span>
          {showCopyButton && (
            <button
              type="button"
              onClick={handleCopy}
              aria-label={copied ? 'Copied' : 'Copy code'}
              className="text-xs text-muted-foreground hover:text-foreground transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring rounded px-1"
            >
              {copied ? 'Copied!' : 'Copy'}
            </button>
          )}
        </div>
        <Highlight theme={themes.vsDark} code={trimmedCode} language={language}>
          {({ style, tokens, getLineProps, getTokenProps }) => (
            <pre
              className="overflow-x-auto p-4 text-xs leading-relaxed m-0"
              style={{ ...style, background: 'transparent' }}
            >
              {tokens.map((line, i) => (
                <div key={i} {...getLineProps({ line })}>
                  {line.map((token, key) => (
                    <span key={key} {...getTokenProps({ token })} />
                  ))}
                </div>
              ))}
            </pre>
          )}
        </Highlight>
      </div>
    );
  }
);
CodeBlock.displayName = 'CodeBlock';

export { CodeBlock };

{
  "id": "code-block",
  "name": "CodeBlock",
  "tier": "atom",
  "description": "Syntax-highlighted code block with language label and copy-to-clipboard button.",
  "designIntent": "Display AI-generated or referenced code readably with one-click copy.",
  "props": [
    {
      "name": "code",
      "type": "string",
      "required": true,
      "description": "Raw code to display."
    },
    {
      "name": "language",
      "type": "string",
      "defaultValue": "tsx",
      "required": false,
      "description": "Prism language identifier."
    },
    {
      "name": "showCopyButton",
      "type": "boolean",
      "defaultValue": true,
      "required": false,
      "description": "Show/hide the copy control."
    }
  ],
  "examples": [
    {
      "title": "Basic",
      "code": "<CodeBlock code={sourceCode} language=\"ts\" />"
    }
  ],
  "antiPatterns": [
    {
      "title": "Do not nest CodeBlock in Response code fences manually",
      "explanation": "Response already routes fenced code to CodeBlock."
    }
  ],
  "accessibility": [
    {
      "feature": "Copy button",
      "implementation": "Icon-labeled button with aria-label that flips to Copied."
    }
  ],
  "package": "@slipstream-ui/ai",
  "importPath": "@slipstream-ui/ai",
  "version": "0.0.1"
}
